window.ScripturaLexicons.BDAG_PART_0167 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-01\" data-source=\"BDAG\" data-search=\"θεοπρεπής, ές adjetivo de dois gêneros digno de Deus; venerável; piedoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοπρεπής, ές</td><td>adjetivo de dois gêneros</td><td>digno de Deus; venerável; piedoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-02\" data-source=\"BDAG\" data-search=\"θεοπρεσβευτής, οῦ, ὁ substantivo masculino embaixador de Deus; enviado autorizado por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοπρεσβευτής, οῦ, ὁ</td><td>substantivo masculino</td><td>embaixador de Deus; enviado autorizado por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-03\" data-source=\"BDAG\" data-search=\"θεός, οῦ substantivo masculino ou feminino Deus; deus; deusa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεός, οῦ</td><td>substantivo masculino ou feminino</td><td>Deus; deus; deusa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-04\" data-source=\"BDAG\" data-search=\"θεοσέβεια, ας, ἡ substantivo feminino reverência a Deus; piedade; religião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοσέβεια, ας, ἡ</td><td>substantivo feminino</td><td>reverência a Deus; piedade; religião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-05\" data-source=\"BDAG\" data-search=\"θεοσεβέω verbo reverenciar a Deus; adorar a Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοσεβέω</td><td>verbo</td><td>reverenciar a Deus; adorar a Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-06\" data-source=\"BDAG\" data-search=\"θεοσεβής, ές adjetivo de dois gêneros temente a Deus; devoto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοσεβής, ές</td><td>adjetivo de dois gêneros</td><td>temente a Deus; devoto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-07\" data-source=\"BDAG\" data-search=\"θεοστυγής, ές adjetivo de dois gêneros odiador de Deus; detestado por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοστυγής, ές</td><td>adjetivo de dois gêneros</td><td>odiador de Deus; detestado por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-08\" data-source=\"BDAG\" data-search=\"θεοστυγία, ας, ἡ substantivo feminino ódio a Deus; inimizade contra Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοστυγία, ας, ἡ</td><td>substantivo feminino</td><td>ódio a Deus; inimizade contra Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-09\" data-source=\"BDAG\" data-search=\"θεότης, ητος, ἡ substantivo feminino divindade; natureza divina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεότης, ητος, ἡ</td><td>substantivo feminino</td><td>divindade; natureza divina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-10\" data-source=\"BDAG\" data-search=\"θεοφιλής, ές adjetivo de dois gêneros amado por Deus; amante de Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοφιλής, ές</td><td>adjetivo de dois gêneros</td><td>amado por Deus; amante de Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-11\" data-source=\"BDAG\" data-search=\"Θεόφιλος, ου, ὁ nome próprio masculino Teófilo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θεόφιλος, ου, ὁ</td><td>nome próprio masculino</td><td>Teófilo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-12\" data-source=\"BDAG\" data-search=\"θεοφόρος, ον adjetivo de dois gêneros portador de Deus; inspirado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεοφόρος, ον</td><td>adjetivo de dois gêneros</td><td>portador de Deus; inspirado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-13\" data-source=\"BDAG\" data-search=\"Θεοφόρος, ου, ὁ nome próprio masculino Teóforo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Θεοφόρος, ου, ὁ</td><td>nome próprio masculino</td><td>Teóforo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-14\" data-source=\"BDAG\" data-search=\"θεραπεία, ας, ἡ substantivo feminino serviço; cuidado; tratamento; cura; servos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεραπεία, ας, ἡ</td><td>substantivo feminino</td><td>serviço; cuidado; tratamento; cura; servos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-15\" data-source=\"BDAG\" data-search=\"θεραπεύω verbo servir; venerar; curar; restaurar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεραπεύω</td><td>verbo</td><td>servir; venerar; curar; restaurar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-16\" data-source=\"BDAG\" data-search=\"θεράπων, οντος, ὁ substantivo masculino servidor; assistente; servo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θεράπων, οντος, ὁ</td><td>substantivo masculino</td><td>servidor; assistente; servo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-17\" data-source=\"BDAG\" data-search=\"θερεία, ας, ἡ substantivo feminino verão; estação estival BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θερεία, ας, ἡ</td><td>substantivo feminino</td><td>verão; estação estival</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-18\" data-source=\"BDAG\" data-search=\"θερίζω verbo ceifar; colher; obter resultados BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θερίζω</td><td>verbo</td><td>ceifar; colher; obter resultados</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-19\" data-source=\"BDAG\" data-search=\"θερινός, ή, όν adjetivo estival; de verão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θερινός, ή, όν</td><td>adjetivo</td><td>estival; de verão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0167-20\" data-source=\"BDAG\" data-search=\"θερισμός, οῦ, ὁ substantivo masculino ceifa; colheita; safra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">θερισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>ceifa; colheita; safra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0167-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοπρεπής, ές</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θεός</span>, <span class=\"greek\">πρέπω</span>; Píndaro, N. 10, 2; também Diodoro Sículo 3, 69, 2; 11, 89, 5; 8; Plutarco, Dio 970 [28, 4]; Fílon, Mos. 2, 15; OGI 383, 57.) Relativo ao que convém a Deus: digno de Deus, reverenciado, venerável, piedoso. Superlativo <span class=\"greek\">θεοπρεπέστατος</span> (Plutarco, Mor. 780f; cf. PGM 1, 178 <span class=\"greek\">ὡς</span> <span class=\"greek\">πρέπον</span> <span class=\"greek\">θεῷ</span>).</p><p class=\"entry-text\">ⓐ De pessoas (Luciano, Alex. 3): <span class=\"greek\">θ</span>. <span class=\"greek\">πρεσβύτης</span>, MPol 7:2. Também de um grupo de pessoas: <span class=\"greek\">θ</span>. <span class=\"greek\">πρεσβυτέριον</span>, ISm 12:2. <span class=\"greek\">συμβούλιον</span> <span class=\"greek\">ἄγειν</span> <span class=\"greek\">θεοπρεπέστατον</span>, «convocar um conselho digno de Deus sob todos os aspectos», IPol 7:3. <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">θεοπρεπεστάτη</span>, ISm, inscrição.</p><p class=\"entry-text\">ⓑ De coisas: Inácio orgulha-se de ter <span class=\"greek\">ὄνομα</span> <span class=\"greek\">θεοπρεπέστατον</span>, «um nome que contribui sobremaneira para a glória de Deus», IMg 1:2 (cf. Máximo de Tiro 35, 2e <span class=\"greek\">θεοπρεπῆ</span> <span class=\"greek\">ὀνόματα</span>, em contraste com <span class=\"greek\">ἀνθρωπικὰ</span> <span class=\"greek\">ὀν</span>.; cf. também o emprego do verbo <span class=\"greek\">πρέπω</span>, «ser apropriado, ser digno de», Justino, A II, 2, 16). Emprega <span class=\"greek\">θ</span>. também a respeito de suas correntes, ISm 11:1. — O. Dreyer, Untersuchungen zum Begriff des Gottgeziemenden in der Antike, ’70. DELG, s.v. <span class=\"greek\">πρέπω</span>; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοπρεσβευτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Pessoa comissionada ou investida de autoridade por Deus, embaixador de Deus (cf. também IPhld 10:1), ISm 11:2 (variante de leitura <span class=\"greek\">θεοπρεσβύτης</span>, Lightfoot, Funk; ver <span class=\"greek\">πρεσβύτης</span>). — DELG, s.v. <span class=\"greek\">πρέσβυς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεός, οῦ</h1><div class=\"entry-meta\"><span>substantivo masculino ou feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e posteriores; Herm. Wr.; inscrições, papiros, LXX, pseudoepígrafos, Fílon, Josefo), masculino <span class=\"greek\">ὁ</span> e feminino <span class=\"greek\">ἡ</span>; vocativo <span class=\"greek\">θεέ</span> (inscrição pisídia [JHS 22, 1902, 355] <span class=\"greek\">θέ</span>; PGM 4, 218 <span class=\"greek\">θεὲ</span> <span class=\"greek\">θεῶν</span>; 7, 529 <span class=\"greek\">κύριε</span> <span class=\"greek\">θεὲ</span> <span class=\"greek\">μέγιστε</span>; 12, 120 <span class=\"greek\">κύριε</span> <span class=\"greek\">θεέ</span>; 13, 997; LXX [Thackeray 145; P. Katz, Philo’s Bible, ’50, 152s.]; ApcMos 42; Josefo, Ant. 14, 24 <span class=\"greek\">ὦ</span> <span class=\"greek\">θεὲ</span> <span class=\"greek\">βασιλεῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὅλων</span>; SibOr 13, 172 <span class=\"greek\">βασιλεῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">θεέ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a>; mais frequentemente (ver 2 e 3c, h, abaixo) <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> (LXX; ParJer 6:12; ApcEsdr 7:5; ApcMos 32; B-D-F §147, 3m; J. Wackernagel, Über einige antike Anredeformen, 1912; Mlt-H. 120). Sobre a presença ou ausência do artigo em geral, ver W-S. §19, 13d; B-D-F §254, 1; 268, 2; Robinson 758; 761; 780; 786; 795; Mlt-Turner 174; B. Weiss, Der Gebrauch des Artikels bei den Gottesnamen, StKr 84, 1911, 319–92; 503–38 (publicado também separadamente). O artigo singular sugere frequentemente uma reivindicação de relação pessoal com uma divindade. «Deus, deus».</p><p class=\"entry-text\">① No mundo greco-romano, o termo <span class=\"greek\">θεός</span> designa sobretudo um ser transcendente que exerce controle extraordinário nos assuntos humanos ou é responsável pela concessão de benefícios incomuns: divindade, deus, deusa (ver <span class=\"greek\">θεά</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 2:4</a> (cf. SibOr 5, 34 <span class=\"greek\">ἰσάζων</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">αὐτόν</span>; Aristides 4, 1 <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰσὶ</span> <span class=\"greek\">θεοί</span>; Taciano 10, 1 <span class=\"greek\">θεὸς</span> … <span class=\"greek\">κύκνος</span> <span class=\"greek\">γίνεται</span> …; Atenágoras 18, 3 <span class=\"greek\">θεός</span> <span class=\"greek\">τις</span> <span class=\"greek\">δισώματος</span>); <span class=\"greek\">θεὸς</span> <span class=\"greek\">Ῥαιφάν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:43</a> (Am 5:26; ver <span class=\"greek\">Ῥαιφάν</span>). <span class=\"greek\">οὐδεὶς</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἷς</span>, «não há deus senão um», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 8:4</a> (cf. AcPl Ha 1, 17, texto reconstituído). <span class=\"greek\">θεοῦ</span> <span class=\"greek\">φωνὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀνθρώπου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:22</a>. — <span class=\"greek\">ἡ</span> <span class=\"greek\">θεός</span>, «a deusa» (no ático; mais raramente em épocas posteriores; Peripl. Eryth. cap. 58; Luciano, Dial. Deor. 17, 2; SIG 695, 28; inscrições, uma das quais se refere a Ártemis em Hauser p. 81s.; Josefo, Ant. 9, 19; Aristides 11, 2 [Ártemis]; Atenágoras 29, 2 [Ino]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:37</a>. No plural, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:40</a> (Êx 32:1); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:11</a>; 19:26; PtK 2 p. 14, 21. <span class=\"greek\">εἴπερ</span> <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">λεγόμενοι</span> <span class=\"greek\">θεοί</span>, «ainda que existam os chamados deuses», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 8:5a</a>; ver v. 5b (sobre <span class=\"greek\">θεοὶ</span> <span class=\"greek\">πολλοί</span>, cf. Josefo, Ant. 4, 149; Máximo de Tiro 11, 5a <span class=\"greek\">θ</span>. <span class=\"greek\">πολλοί</span> com <span class=\"greek\">εἷς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">πατήρ</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">φύσει</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὄντες</span> <span class=\"greek\">θεοί</span>, «aqueles que por natureza não são verdadeiramente deuses», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4:8b</a> (cf. Aristides 4, 2 <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">θεόν</span> e outros). <span class=\"greek\">θεοὶ</span> … <span class=\"greek\">λίθινοι</span> etc., AcPl Ha 1, 18 (cf. JosAs 10:13 <span class=\"greek\">τοὺς</span> <span class=\"greek\">χρυσοῦς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀργυροῦς</span>). Sobre o diabo: <span class=\"greek\">μὴ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">θεός</span>, AcPlCor 2:15.</p><p class=\"entry-text\">② Alguns escritos da literatura examinada empregam <span class=\"greek\">θ</span>. com referência a Cristo (sem necessariamente identificar Cristo com o Pai e, portanto, em harmonia com o Shemá de Israel, Dt 6:4; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:18</a> e 4a, abaixo), embora a interpretação de certas passagens seja debatida. Nas tradições mosaica e greco-romana, o componente semântico fundamental na compreensão de divindade é o fator de atuação: o caráter salvador ou as contribuições extraordinárias à sociedade. Dg 10:6 define essa perspectiva antiga: <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λάβων</span> <span class=\"greek\">ἔχει</span>, <span class=\"greek\">ταῦτα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐπιδεομένοις</span> <span class=\"greek\">χορηγῶν</span>, <span class=\"greek\">θεὸς</span> <span class=\"greek\">γίνεται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λαμβανάντων</span>, «aquele que oferece aos necessitados o que recebeu de Deus torna-se um deus para os beneficiários» (cf. Sb III, 6263, 27s., acerca de uma mãe). Esse entendimento levou à extensão do sentido de <span class=\"greek\">θ</span>. a pessoas que despertam reverência especial (cf. passagens sob 4, abaixo; desenvolvimento semelhante pode ser observado no emprego de <span class=\"greek\">σέβομαι</span> e cognatos).</p><p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:5</a>, a interpretação é dificultada pela necessidade de acrescentar sinais de pontuação ao texto impresso. Se se põe ponto antes de <span class=\"greek\">ὁ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">κτλ</span>., a doxologia se refere a Deus tal como definido na tradição de Israel (assim E. Abbot, JBL 1, 1881, 81–154; 3, 1883, 90–112; R. Lipsius; H. Holtzmann, Ntl. Theol.² II, 1911, 99s.; E. Günther, StKr 73, 1900, 636–44; F. Burkitt, JTS 5, 1904, 451–55; Jülicher; P. Feine, Theol. d. NTs⁶, ’34, 176 e outros; texto da RSV; margem da NRSV). Consideração especial favorável a essa interpretação é a posição atribuída a Cristo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.25-28\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:25–28</a> e a probabilidade de Paulo não ter transgredido a proibição de Dt 5:7. — Se se põe vírgula no mesmo lugar, a referência é a Cristo (assim B. Weiss; E. Bröse, NKZ 10, 1899, 645–57 e outros; texto da NRSV; margem da RSV; ver também <span class=\"greek\">εἰμί</span> 1). Indeciso: T. Haering. A transposição <span class=\"greek\">ὧν</span> <span class=\"greek\">ὁ</span>, «a quem pertence», proposta pelo estudioso sociniano J. Schlichting (falecido em 1661), foi retomada por J. Weiss, D. Urchristentum, 1917, 363; W. Wrede, Pls, 1905, 82; C. Strömman, ZNW 8, 1907, 319s.</p><p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:1</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 5:20</a>, a interpretação é passível de questionamento (mas cf. ISmyrna McCabe .0010, 100 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">Ἀντίοχος</span>). Em todo caso, <span class=\"greek\">θ</span>. certamente se refere a Cristo, como aquele que manifesta características primárias da divindade, nas seguintes passagens do NT: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:1b</a> (com <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> em 1:1a, que se refere a Deus no contexto monoteísta da tradição de Israel. Sobre o problema suscitado por tal atribuição, ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:34</a> [cf. Êx 7:1; Sl 81:6]; sobre <span class=\"greek\">θεός</span> com artigo e sem artigo, conforme signifique Deus ou o Logos, ver Fílon, Somn. 1, 229s.; J. Griffiths, ET 62, ’50/51, 314–16; B. Metzger, ET 63, ’51/52, 125s.), 18b. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριός</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">μου</span>, «meu Senhor e meu Deus!» (nominativo com artigo equivalente a vocativo; ver o início deste verbete. — Sobre uma ressurreição como prova de divindade, cf. Diógenes Laércio 8, 41, que cita Hermipo: Pitágoras retorna de uma viagem ao Hades e aparece entre seus seguidores [<span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span>], que o consideram <span class=\"greek\">θεῖόν</span> <span class=\"greek\">τινα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20:28</a> (sobre a associação de <span class=\"greek\">κύριος</span> e <span class=\"greek\">θεός</span>, ver 3c, abaixo). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:13</a> (<span class=\"greek\">μέγας</span> <span class=\"greek\">θ</span>.). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:8</a>, 9 (citação de Sl 44:7, 8). Ver T. Glasson, NTS 12, ’66, 270–72. Jd 5, P72.</p><p class=\"entry-text\">Acima de tudo, Inácio chama Cristo de <span class=\"greek\">θεός</span> em numerosas passagens: <span class=\"greek\">θεὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">Χριστός</span>, ITr 7:1; <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">θεός</span>, ISm 10:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἡμῶν</span>, IEph, inscrição; 15:3; 18:2; IRo, inscrição (duas vezes); 3:3; IPol 8:3; <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μου</span>, IRo 6:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">θεοῦ</span>, IEph 1:1. <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">γενόμενος</span> <span class=\"greek\">θεός</span>, 7:2. <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἀνθρωπίνως</span> <span class=\"greek\">φανερούμενος</span>, 19:3. <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">σοφίσας</span>, ISm 1:1. — Hdb. exc. 193s.; M. Rackl, Die Christologie d. hl. Ign. v. Ant., 1914. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">μου</span> <span class=\"greek\">Χριστὲ</span> <span class=\"greek\">Ἰησοῦ</span>, AcPl Ha 3, 10; <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>[<span class=\"greek\">εός</span>], 6, 24; cf. linha 34 (cf. também Justino, A I, 63, 15; D. 63, 5 e outros; Taciano 13, 3; Atenágoras 24, 1; Melitão, P. 4, 28 e outros). — S. Lösch, Deitas Jesu u. antike Apotheose, ’33; cf. A. Wlosk, Römischer Kaiserkult, ’78.</p><p class=\"entry-text\">③ Deus na perspectiva monoteísta israelita e cristã: Deus, emprego predominante, ora com artigo, ora sem artigo.</p><p class=\"entry-text\">ⓐ <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a>; 3:9; 5:8, 34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:12</a>; 10:18; 13:19 (cf. TestJob 37:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:2b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:22b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:6</a> e outros. Com preposição: <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:15</a>; <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:42b</a>, 47; 1Jo 3:9s.; 4:1ss., 6s.; 5:1, 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 3:5</a>; 5:18 e outros; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 5:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:3</a> (Atenágoras 21, 1); <span class=\"greek\">ἔναντι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:8</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:19</a>; 26:18, 20 (Justino, D. 101, 1); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:47</a> (Justino, D. 8, 2); <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:40</a> (Aristides 4, 2; Justino, A I, 33, 6 e outros; sem artigo, Justino, D. 69, 6 e outros); <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:13</a>; 9:14 (Justino, A I, 28, 3; Taciano 7, 1; Atenágoras 31, 2 e outros); <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:16</a>; AcPl Ha 3, 8 (Justino, D. 39, 1; Melitão, HE 4, 26, 13 e outros).</p><p class=\"entry-text\"><span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a>; 5:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:17</a>, é acusativo de relação: «no tocante à relação com Deus ou às coisas referentes a Deus, na causa de Deus» (ver B-D-F §160; Robinson 486. Sobre <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>., ver Sófocles, Phil. 1441; Xenofonte, De Rep. Lac. 13, 11; Aristóteles, Pol. 1314b, 39; Luciano, Pro Imag. 8; Mitt-Wilck. I/2, 109, 3 [séc. III a.C.] <span class=\"greek\">εὐσεβὴς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεούς</span>; Êx 4:16; 18:19; Josefo, Ant. 9, 236 <span class=\"greek\">εὐσεβὴς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>[<span class=\"greek\">ὸν</span>] <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐτήρουσαν</span>, «quando observavam as coisas referentes a Deus», AcPl Ha 8, 13 (=<span class=\"greek\">τα</span> <span class=\"greek\">π̣ρος</span> <span class=\"greek\">θ̣̄ν̄</span>| <span class=\"greek\">ἐτήρουσαν</span>, Ox 1602, 10s. = BMM, recto, 16, reconstituído a partir do que precede).</p><p class=\"entry-text\">ⓑ Sem artigo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:14</a>; 20:38; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:18a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:8</a>, 33b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:21</a>; 5:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 2:19</a>; 4:8s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:16</a>; 3:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:4</a>; AcPl Ha 8, 20 = BMM, recto, 25 (ver também a revisão de H. Sanders de Ox 1602, 26 em HTR 31, ’38, 79, nota 2, Ghent 62, verso, 6); AcPlCor 1:15; 2:19, 26. Com preposição: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 3:2a</a>; 16:30 (Justino, A II, 13, 4 <span class=\"greek\">τὸν</span> … <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀγεννήτου</span> … <span class=\"greek\">θεοῦ</span> <span class=\"greek\">λόγον</span>); <span class=\"greek\">εἰς</span> <span class=\"greek\">θεόν</span>, IPhld 1:2; <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span> (Píndaro, O. 11, 10; P. 1, 41; Josefo, Ant. 2, 164; Justino, A I, 22, 2; Melitão, P. 55, 404), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 5:39</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:9</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 2:17</a>; Jd 1; AcPl Ha 1, 15; 2, 35; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θεόν</span>, AcPl Ha 2, 29 (cf. <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεόν</span>, Justino, D. 138, 2). <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεόν</span>, «segundo a vontade de Deus» (Apiano, Iber. 19 §73; 23 §88; 26 §101; Liby. 6 §25; Bell. Civ. 4, 86 §364), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8:27</a>; 2Co 7:9ss.; IEph 2:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἀγάπη</span>, «amor piedoso», IMg 1:1; cf. 13:1; ITr 1:2. <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῷ</span> (Josefo, Bell. 1, 635), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:52</a>.</p><p class=\"entry-text\">ⓒ Com genitivo seguinte ou com <span class=\"greek\">ἴδιος</span>, para indicar uma relação especial: <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">Ἀβραάμ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 3:13</a>; 7:32 (todos citando Êx 3:6). <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">Ἰσραήλ</span> (Ez 44:2; JosAs 7:5), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.68\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:68</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">μου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:3</a>; 4:19; Fm 4. No AT, <span class=\"greek\">κύριος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">σου</span> (<span class=\"greek\">ἡμῶν</span>, <span class=\"greek\">ὑμῶν</span>, <span class=\"greek\">αὐτῶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:7</a> (Dt 6:16); 22:37 (Dt 6:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:29</a> (Dt 6:4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:16</a>; 4:8 (Dt 6:13); 10:27 (Dt 6:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:39</a>.</p><p class=\"entry-text\"><span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:11</a> (Justino, D. 12, 3; a combinação de <span class=\"greek\">κύριος</span> e <span class=\"greek\">θεός</span> é frequente no AT: 2Km 7:28; 3Km 18:39; Jr 38:18; Zc 13:9; Sl 29:3; 34:23; 85:15; 87:2; TestAbr A 3 p. 79, 19 [Stone p. 6]; JosAs 3:4; 12:2 <span class=\"greek\">κύριε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰώνων</span>. Mas ver também Epicteto 2, 16, 13 <span class=\"greek\">κύριε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> [G. Breithaupt, Her. 62, 1927, 253–55]; Herm. Wr.: Cat. Cod. Astr. VIII/2, p. 172, 6 <span class=\"greek\">κύριε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἡμῶν</span>; a referência PGM no início deste verbete; e os usos sacros <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">Σοκνοπαίῳ</span> [OGI 655, 3s. — 24 a.C.]; PTebt 284, 6; <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">Ἀσκληπίῳ</span> [Sb 159, 2]; deo domino Saturno [inscrição da época imperial de Thala, na província da África: BPhW 21, 1901, 475]; também Suetônio, Domit. 13 dominus et deus noster [sobre a formulação, ver 4a: PMich 209]; Aristides 15, 10; Justino, D. 60, 3 e outros). <span class=\"greek\">τὸν</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">θ</span>., AcPl Ha 3, 22. — <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:17</a>.</p><p class=\"entry-text\">ⓓ Empregado com <span class=\"greek\">πατήρ</span> (ver <span class=\"greek\">πατήρ</span> 6a): <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:3</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:3</a>; 3:11, 13. <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">πατήρ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:27</a>. <span class=\"greek\">θ</span>. <span class=\"greek\">πατήρ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 8:6</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἡμῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:7b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:2</a>; Fm 3; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">π</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1:3</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1:4</a>; <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">π</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 1:17</a>; 2Jo 3.</p><p class=\"entry-text\">ⓔ Com genitivo daquilo que Deus produz, em conformidade com a natureza divina: <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰρήνης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:23</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span>, «o Deus de quem provém a esperança», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15:13</a>. <span class=\"greek\">πάσης</span> <span class=\"greek\">παρακλήσεως</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:3b</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀγάπης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">13:11</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">πάσης</span> <span class=\"greek\">χάριτος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 5:10</a>. Em <span class=\"greek\">οὐ</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀκαταστασίας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.33\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:33</a>, deve-se suprir <span class=\"greek\">θεός</span> antes de <span class=\"greek\">ἀκατ</span>.: «pois Deus não é um Deus de desordem».</p><p class=\"entry-text\">ⓕ O genitivo (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">θεοῦ</span> é empregado como segue:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Genitivo subjetivo, extremamente frequente, dependente de palavras como <span class=\"greek\">βασιλεία</span>, <span class=\"greek\">δόξα</span>, <span class=\"greek\">θέλημα</span>, <span class=\"greek\">ἐντολή</span>, <span class=\"greek\">εὐαγγέλιον</span>, <span class=\"greek\">λόγος</span>, <span class=\"greek\">ναός</span>, <span class=\"greek\">οἶκος</span>, <span class=\"greek\">πνεῦμα</span>, <span class=\"greek\">υἱός</span>, <span class=\"greek\">υἱοί</span>, <span class=\"greek\">τέκνα</span> e muitas outras. Provavelmente pertence aqui (ver <span class=\"greek\">β</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">μωρὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>., «a (aparente) loucura de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:25</a> (ver B-D-F §263, 2).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Genitivo objetivo: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «amor por Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:42</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">προσευχὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., «oração a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:12</a>. <span class=\"greek\">πίστις</span> <span class=\"greek\">θεοῦ</span>, «fé em Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:22</a>. <span class=\"greek\">φόβος</span> <span class=\"greek\">θεοῦ</span>, «temor de Deus, reverência a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3:18</a> e outros (ver <span class=\"greek\">φόβος</span> 2b<span class=\"greek\">α</span>). Se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:25</a> deve ser incluído aqui (ver <span class=\"greek\">α</span>, acima), <span class=\"greek\">τὸ</span> <span class=\"greek\">μωρὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>. se refere à fidelidade apostólica a Deus, considerada loucura pelos de fora.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, «as coisas, os caminhos, os pensamentos ou os propósitos secretos de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 2:11</a>. <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:33</a>; ver <span class=\"greek\">φρονέω</span> 2b (<span class=\"greek\">ἀτιμάζοντας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>., Justino, D. 78, 10 e outros). <span class=\"greek\">ἀποδιδόναι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «dar a Deus o que pertence a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:25</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. Quase como substituto do adjetivo «divino», IMg 6:1s.; 15 (cf. Atenágoras 21, 4 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">θεοῦ</span> [sobre Zeus]).</p><p class=\"entry-text\">ⓖ O dativo <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (ver B-D-F §188, 2; 192; Robinson 538s.; W. Havers, Untersuchungen z. Kasussyntax d. indogerm. Sprachen, 1911, 162ss.) é empregado como segue:</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Dativo de vantagem (cf. por exemplo Atenágoras 26, 3 <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐπηκόῳ</span> <span class=\"greek\">θεῷ</span>), «para Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 5:13</a>. Talvez (ver <span class=\"greek\">β</span>) <span class=\"greek\">ὅπλα</span> <span class=\"greek\">δυνατὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">10:4</a>. O dativo de Rm 6:10s. expressa, antes, o possuidor.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Dativo ético, «aos olhos de Deus», donde o valor de superlativo (ver Beginn. IV, 75, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:20</a>), «muito»: <span class=\"greek\">μεγάλοι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., B 8:4 (cf. Jn 3:3). <span class=\"greek\">ἀστεῖος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:20</a>. Talvez (ver <span class=\"greek\">α</span>) <span class=\"greek\">ὅπλα</span> <span class=\"greek\">δυνατὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>., «armas poderosas aos olhos de Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10:4</a>. Normalmente, essa ideia é expressa por <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>.</p><p class=\"entry-text\">ⓗ <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. é empregado como vocativo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:34</a> (Sl 21:2. <span class=\"greek\">θεός</span> duas vezes no início da invocação de uma oração: Élio Dionísio <span class=\"greek\">θ</span>, 8; Pausânias, Attic. <span class=\"greek\">θ</span>, 7: ‘<span class=\"greek\">θεὸς</span> <span class=\"greek\">θεός</span>’ <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀρχαῖς</span> <span class=\"greek\">ἐπέλεγον</span> <span class=\"greek\">ἐπιφημιζόμενοι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:8</a> (Sl 44:7; M. Harris, TynBull 36, ’85, 129–62); 10:7 (Sl 39:9); AcPl Ha 3, 10; 5, 12; 31. Ver também 2 e 3c e o início deste verbete.</p><p class=\"entry-text\">ⓘ <span class=\"greek\">θ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰώνων</span>, ver <span class=\"greek\">αἰών</span> 3 e 4; <span class=\"greek\">θ</span>. <span class=\"greek\">αἰώνιος</span>, ver <span class=\"greek\">αἰώνιος</span> 2; <span class=\"greek\">θ</span>. <span class=\"greek\">ἀληθινός</span>, ver <span class=\"greek\">ἀληθινός</span> 3b; <span class=\"greek\">εἷς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, ver <span class=\"greek\">εἷς</span> 2b; (<span class=\"greek\">ὁ</span>) <span class=\"greek\">θ</span>. (<span class=\"greek\">ὁ</span>) <span class=\"greek\">ζῶν</span>, ver [<span class=\"greek\">ζάω</span>] 1a<span class=\"greek\">ε</span>. — <span class=\"greek\">ὁ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">θεός</span>, «o único Deus» (4Km 19:15, 19; Sl 85:10; Is 37:20; Dn 3:45; Fílon, Leg. All. 2, 1s.; ver Norden, Agn. Th. 145), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:44</a> (alguns manuscritos omitem <span class=\"greek\">τοῦ</span> <span class=\"greek\">μόνου</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:17</a>. — <span class=\"greek\">ὁ</span> <span class=\"greek\">μόνος</span> <span class=\"greek\">ἀληθινὸς</span> <span class=\"greek\">θ</span>. (Demócares, 75 Fgm. 2 p. 135, 7 Jac. [em Ateneu 6, 62, 253c] <span class=\"greek\">μόνος</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἀληθινός</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17:3</a>. Cf. combinações semelhantes com <span class=\"greek\">μόνος</span> <span class=\"greek\">θ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:27</a>; Jd 25. <span class=\"greek\">μόνος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">μένει</span>, AcPl Ha 2, 27. — <span class=\"greek\">θ</span>. <span class=\"greek\">σωτήρ</span>, ver <span class=\"greek\">σωτήρ</span> 1. — O. Holtzmann, D. chr. Gottesglaube, s. Vorgesch. u. Urgesch., 1905; Ev. Dobschütz, Rationales u. irrat. Denken über Gott im Urchristent.: StKr 95, 1924, 235–55; R. Hoffmann, D. Gottesbild Jesu, ’34; P. Althaus, D. Bild Gottes b. Pls: ThBl 20, ’41, 81–92; Dodd 3–8; K. Rahner, Theos im NT: Bijdragen (Maastricht) 11, ’50, 212–36; 12, ’51, 24–52.</p><p class=\"entry-text\">④ Aquilo que não é transcendente, mas é considerado digno de reverência ou respeito especiais: deus (Artemidoro 2, 69 p. 161, 17: <span class=\"greek\">γονεῖς</span> e <span class=\"greek\">διδάσκαλοι</span> são como deuses; Simplício, em Epicteto p. 85, 27: segundo o antigo costume romano, os filhos deviam chamar seus pais de <span class=\"greek\">θεοί</span>; ver 2, acima, e a nota sobre <span class=\"greek\">σέβομαι</span>).</p><p class=\"entry-text\">ⓐ Acerca de seres humanos: <span class=\"greek\">θεοί</span> (como אֱלֹהִים), Jo 10:34s. (Sl 81:6; seres humanos são chamados <span class=\"greek\">θ</span>. no AT também em Êx 7:1; 22:27; cf. Fílon, Det. Pot. Insid. 161s.; Somn. 1, 229; Mut. Nom. 128; Omn. Prob. Lib. 43; Mos. 1, 158; Decal. 120; Leg. All. 1, 40; Migr. Abr. 84). <span class=\"greek\">θ</span>. <span class=\"greek\">γίνεται</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">λαμβανόντων</span>, «um benfeitor demonstra ser um deus para os beneficiários», Dg 10:6 (cf. Plínio, NH 2, 7, 18; ver 2, acima, início. — Aristóteles, Pol. 3, 8, 1, 1284a, acerca de pessoa superior como deus entre seres humanos; Arcesilau [séc. III a.C.] descreve Crates e Pólemon como <span class=\"greek\">θεοί</span> <span class=\"greek\">τινες</span>, «uma espécie de deuses» [Diógenes Laércio 4, 22]; Antífanes diz do poeta iâmbico Filóxeno <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνθρώποισιν</span> <span class=\"greek\">ἦν</span> [Ateneu 14, 50, 643d]; Diodoro Sículo 1, 4, 7 e 5, 21, 2 acerca de César; sobre honrarias concedidas a Demétrio, ver I. Kertész, Bemerkungen zum Kult des Demetrios Poliorketes: Oikumene 2, ’78, 163–75 [bibliografia]; Díon Crisóstomo 30 [47], 5 <span class=\"greek\">Πυθαγόρας</span> <span class=\"greek\">ἐτιμᾶτο</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">θεός</span>; Heliodoro 4, 7, 8 <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεός</span>, dirigido a um médico; BGU 1197, 1 [4 a.C.], um alto funcionário, e 1201, 1 [2 a.C.], um sacerdote <span class=\"greek\">θεός</span> e <span class=\"greek\">κύριος</span>; PMich 209, 11s. [sécs. II/III d.C.] <span class=\"greek\">οἶδας</span> <span class=\"greek\">ἄδελφε</span>, <span class=\"greek\">ὅτει</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">ὧς</span> <span class=\"greek\">ἀδελφόν</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἔχω</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κύριον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεόν</span>; Justino, A I, 26, 2 [<span class=\"greek\">Σίμων</span>] <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐνομίσθη</span> <span class=\"greek\">καὶ</span> … <span class=\"greek\">ὡς</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τετίμηται</span>; Taciano 3, 2 <span class=\"greek\">μὴ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὤν</span> [Empédocles]; Atenágoras 30, 2 <span class=\"greek\">Ἀντίνους</span> … <span class=\"greek\">ἔτυχε</span> <span class=\"greek\">νομίζεσθαι</span> <span class=\"greek\">θεός</span>; de benfeitores em geral, AcJ 27 [Aa II/1, 166, 4]). — J. Emerton, JTS 11, ’60, 329–32.</p><p class=\"entry-text\">ⓑ Do ventre (= apetite), como deus de certas pessoas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3:19</a> (cf. Ateneu 3, 97c <span class=\"greek\">γάστρων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κοιλιοδαίμων</span>; também Êupolis Com. [séc. V a.C.] Fgm. 172 K. [em Ateneu 3, 100b]; sobre o emprego de <span class=\"greek\">θ</span>. para entidades impessoais [por exemplo, Eurípides, Cyclops 316, da riqueza como deus], ver DDD 693s.).</p><p class=\"entry-text\">⑤ Sobre o diabo: <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:4</a> (ver <span class=\"greek\">αἰών</span> 2a e W. Müllensiefen, StKr 95, 1924, 295–99). — 668–99; RAC XI 1202–78; XII 81–154; B. 1464; LfgrE, s.v. <span class=\"greek\">θεός</span>, col. 1001 (bibliografia); Schmidt, Syn. IV 1–21; DELG; M-M; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοσέβεια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes seguintes; Xenofonte, An. 2, 6, 26; Platão, Epin. p. 985d; 989e; Gn 20:11; Jó 28:28; Sir 1:25; Bar 5:4; Fílon, Justino; Taciano 17, 3; Atenágoras 4, 2; Teófilo de Antioquia 3, 15 [p. 234, 16]. A palavra ocorre como título em inscrições cristãs; cf. PLond 1924, 4; 1925, 3s.; 1929, 3 [todas do séc. IV d.C.].) Reverência a Deus ou conjunto de crenças e práticas relacionadas ao interesse por Deus: piedade, devoção, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:10</a>; religião, 2Cl 20:4; Dg 1; 3:3; 4:5; Qua (1). <span class=\"greek\">ἀόρατος</span> <span class=\"greek\">θ</span>., «culto invisível» (isto é, sem imagens, sacrifícios ou cerimônias elaboradas, com ênfase na vida interior; ver vv. 5–7), Dg 6:4. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπλανῆ</span> <span class=\"greek\">θεοσέβειαν</span>, «culto isento de erro», tal como recomendado pelos profetas de Israel, aparentemente em referência à ênfase nas disposições interiores, AcPlCor 2:10. <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">μυστήριον</span>, Dg 4:6 (Wengst 343, nota 34). — DELG, s.v. <span class=\"greek\">σέβομαι</span>; M-M; TW; Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοσεβέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver verbete precedente; Pólux 1, 22; Cássio Dio 54, 30, 1; SIG 708, 18 [séc. II a.C.]; TestJos 6:7; Justino, D. 46, 6; Atenágoras.) Ter reverência por Deus, adorar a Deus; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">Ἰουδαῖοις</span>, «do mesmo modo que os judeus», Dg 3:1. — L. Feldman, Bar 12, ’86, 58–63 (inscrições); DELG, s.v. <span class=\"greek\">σέβομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοσεβής, ές</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes precedentes; Sófocles, Heródoto e posteriores; Vécio Valente 17, 1; 19; 18, 16; Herm. Wr. 9, 4b; IG XIV, 1325; Kaibel 729, 2; PGiss 55, 1; UPZ 14, 20 [158 a.C.], sobre o qual ver nota do editor, p. 159; LXX; TestAbr A 4, p. 81, 4 [Stone p. 10]; TestNapht 1:10; JosAs; EpArist 179; Fílon, Mut. Nom. 197; Josefo, C. Ap. 2, 140; Justino [D. 118, 3 <span class=\"greek\">θεοσεβέστεροι</span>]; Taciano 13, 3; Atenágoras 37, 1. Cf. também Josefo, Ant. 12, 284; 20, 195, e a inscrição judaica no teatro de Mileto em Deissmann, LO 391s. [LAE 446s.], Schürer III 164–72, SAB 1897, 221ss.; inscrições em B. Wander, Gottesfürchtige und Sympathisanten [WUNT 104], ’98, 87–137, com cautela quanto à pertinência para os dados bíblicos.) Temente a Deus, devoto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9:31</a>. Com <span class=\"greek\">θεοφιλής</span>: <span class=\"greek\">γένος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Χριστιανῶν</span>, MPol 3:2. Referente a Jó, 1Cl 17:3 (Jó 1:1). — Lampe, s.v.; DELG, s.v. <span class=\"greek\">σέβομαι</span>; ver SEG XLII, 726 e 1226; M-M; TW; Spicq; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοστυγής, ές</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Nos testemunhos citáveis de épocas anteriores, ocorre somente em sentido passivo, «detestado por Deus» (Eurípides, Tro. 1213, Cycl. 396; 602; Sófocles, Inachus [POxy 2369]; Neófron, TrGF I, 2, 4; Atenágoras 30, 1), passando depois a «abandonado por Deus». Na lista de vícios de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:30</a>, parece preferível o sentido ativo, «que odeia a Deus» (A. Debrunner, Griech. Wortbildungslehre, 1917, 52 §105). É claramente ativo em Pseudo-Clemente, Hom. 1, 12 <span class=\"greek\">ἄδικοι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεοστυγεῖς</span>. O substantivo <span class=\"greek\">θεοστυγία</span>, 1Cl 35:5, também deve ser entendido no sentido ativo. Em favor do sentido passivo: Goodspeed («abominável a Deus»); Moffatt («detestado por Deus»); margem da NRSV; Vulgata latina; ver Robinson 232. — C. Fritzsche (1836), sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:30</a>; C. Cranfield, Ro (ICC), ad loc. (bibliografia); DELG, s.v. <span class=\"greek\">στυγέω</span>; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοστυγία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Hápax legómenon: ódio ou inimizade contra Deus, 1Cl 35:5 (ver <span class=\"greek\">θεοστυγής</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Plutarco, Mor. 415bc: <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἥρωας</span>, <span class=\"greek\">ἐκ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἡρώων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δαίμονας</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">βελτίονες</span> <span class=\"greek\">ψυχαὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μεταβολὴν</span> <span class=\"greek\">λαμβάνουσιν</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">δαιμόνων</span> <span class=\"greek\">ὀλίγαι</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">χρόνῳ</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">καθαρθεῖσαι</span> <span class=\"greek\">παντάπασι</span> <span class=\"greek\">θεότητος</span> <span class=\"greek\">μετέσχον</span>, «assim, dentre os homens, as almas melhores passam a heróis e, dentre os heróis, a semideuses; e, dentre os semideuses, algumas poucas, purificadas pela virtude ao longo de muito tempo, participam plenamente da divindade»; Luciano, Icarom. 9; ApcSed 2:4 e outros; Taciano 12, 4; 21, 2; Melitão, Fgm. 6; Herm. Wr. 12, 1; 13, 7a; Proclo, Theol. 137 p. 122, 5 e outros; Cleópatra 62; 117; 137; <span class=\"greek\">οἱ</span> <span class=\"greek\">αἱρετικοὶ</span> <span class=\"greek\">διαφόρους</span> <span class=\"greek\">εἰσάγοντες</span> <span class=\"greek\">θεότητας</span>, Dídimo, Gen. 184, 28; <span class=\"greek\">θ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span>, Orígenes, C. Cels. 2, 36, 17.) Condição de ser deus, caráter ou natureza divina, deidade, divindade; empregado como substantivo abstrato correspondente a <span class=\"greek\">θεός</span> (Orígenes, C. Cels. 7, 25, 9): <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «a plenitude da divindade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:9</a> (ver Nash, s.v. <span class=\"greek\">θειότης</span>). <span class=\"greek\">ἐπιζητεῖν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «investigar a divindade», Hm 10, 1, 4; cf. 5s. <span class=\"greek\">δύναμις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «poder da divindade», 11:5; <span class=\"greek\">πνεῦμα</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">θ</span>., 11:10, 14. — DELG, s.v. <span class=\"greek\">θεός</span>; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοφιλής, ές</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Amado por Deus, estimado por Deus (assim Píndaro, Heródoto e outros; Diodoro Sículo 5, 34, 1; Díon Crisóstomo 16 [33], 21; OGI 383, 42 [séc. I a.C.]; PGM 13, 225; EpArist 287; Josefo, Ant. 1, 106; 14, 22; 455; Justino, D. 7, 1; Taciano 12, 3); também em sentido ativo, «que ama a Deus» (Isócrates 4, 29; Fílon, Praem. 43), com <span class=\"greek\">θεοσεβής</span>, MPol 3:2. — DELG, s.v. <span class=\"greek\">θεός</span>; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεόφιλος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Na literatura [por exemplo, Diodoro Sículo 16, 53, 1], bem como em inscrições e papiros [desde o séc. III a.C.], empregado para judeus [EpArist 49; Josefo] e gentios.) Teófilo.</p><p class=\"entry-text\">① Cristão de posição destacada, a quem são dedicados o Evangelho de Lucas (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1:3</a>) e Atos (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:1</a>).</p><p class=\"entry-text\">② Um presbítero de Corinto, AcPlCor 1:1. — Haenchen, sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:1</a>; cf. DELG, s.v. <span class=\"greek\">θεός</span>; M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεοφόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo de dois gêneros</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Que traz Deus, portador de Deus; inspirado, inspirado por Deus (Ésquilo, Fgm. 225; Filodemo, <span class=\"greek\">π</span>. <span class=\"greek\">θεῶν</span> 1, coluna 4, 12 Diels: «que traz dentro de si o espírito divino»; Leôncio 12 p. 22, 14; 15 p. 30, 15; AJA 37, 244 [inscrição do séc. II d.C.; mistérios báquicos]. — Heráclito, Ep. 8, 2, a <span class=\"greek\">Σίβυλλα</span> como <span class=\"greek\">θεοφορουμένη</span> <span class=\"greek\">γυνή</span>). Substantivado, <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>., «o portador de Deus», IEph 9:2 (ver o verbete seguinte e cf. a variante de leitura de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:20</a> nos manuscritos latinos: portate [=<span class=\"greek\">ἄρατε</span>] deum in corpore vestro). — Cf. DELG, s.v. <span class=\"greek\">θεός</span>; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Θεοφόρος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Não encontrado como nome próprio antes de Inácio e talvez cunhado por ele ou para ele; sobre a palavra e o nome, ver Hdb., Ergänzungsband, 1923, 189–91. — Élio Aristides, em virtude de sua relação próxima com Asclépio, recebe o sobrenome <span class=\"greek\">Θεόδωρος</span>: 50, 53s. K. = 26 p. 518 D.) Teóforo, sobrenome de Inácio: IEph, inscrição; IMg, inscrição; ITr, inscrição; IRo, inscrição; IPhld, inscrição; ISm, inscrição; IPol, inscrição. — DELG, s.v. <span class=\"greek\">θεός</span>; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεραπεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes seguintes; Eurípides, Heródoto e posteriores; inscrições, papiros, LXX, TestJob 38:8; JosAs, EpArist, Fílon, Josefo; Justino, A I, 9, 3; Atenágoras, R. 49, 10 e outros; Justino, A I, 12, 5, e Taciano 34, 2: «serviço cultual».) Em geral, «servir, serviço, cuidado», prestado a outrem.</p><p class=\"entry-text\">① Emprego de recursos médicos no tratamento dos enfermos, tratamento, especialmente cura (Hipócrates e outros; PTebt 44, 6–9 [114 a.C.] <span class=\"greek\">ὄντος</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θεραπείᾳ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> … <span class=\"greek\">Ἰσιείῳ</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀρρωστίας</span>, «quando eu estava no ... santuário de Ísis para tratamento de uma enfermidade»; Sb 159, 4s.; 1537b; TestJob 38:8).</p><p class=\"entry-text\">ⓐ Literalmente (Diodoro Sículo 1, 25, 7 [plural]; 17, 89, 2; Luciano, Abdic. 7; Fílon, Deus Imm. 63; Josefo, Vi. 85), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:11</a>. <span class=\"greek\">θεραπείας</span> <span class=\"greek\">ποιεῖν</span>, «realizar curas», Ox 1, recto, 12s. (ASyn. 33, 85; cf. GTh 31); <span class=\"greek\">τὰς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">ἐπετέλουν</span>, GJs 20:2 (códices, não o papiro).</p><p class=\"entry-text\">ⓑ Figuradamente, com genitivo objetivo (cf. Platão, Prot. 345a <span class=\"greek\">τ</span>. <span class=\"greek\">καμνόντων</span>; Sb 1537b; <span class=\"greek\">θ</span>. <span class=\"greek\">ὅλου</span> <span class=\"greek\">σώματος</span>; SIG 888, 125; Fílon, Spec. Leg. 1, 191 <span class=\"greek\">θ</span>. <span class=\"greek\">ἁμαρτημάτων</span>), <span class=\"greek\">θ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22:2</a>.</p><p class=\"entry-text\">② Equivalente a <span class=\"greek\">οἱ</span> <span class=\"greek\">θεράποντες</span>, «servos» (Heródoto e outros; Gn 45:16; Et 5:2b; JosAs; Fílon, In Flacc. 149; Josefo, Bell. 1, 82; Ant. 4, 112); <span class=\"greek\">καταστῆσαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>., «colocar alguém à frente dos servos» (cf. Políbio 4, 87, 5 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τεταγμένος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:45</a>, variante de leitura. — DELG, s.v. <span class=\"greek\">θεράπων</span>; M-M; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεραπεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐθεράπευον</span>; futuro <span class=\"greek\">θεραπεύσω</span>; 1º aoristo <span class=\"greek\">ἐθεράπευσα</span>. Passiva: imperfeito <span class=\"greek\">ἐθεραπευόμην</span>; 1º aoristo <span class=\"greek\">ἐθεραπεύθην</span>; particípio perfeito <span class=\"greek\">τεθεραπευμένος</span> (ver verbete precedente e seguinte; Homero e posteriores; inscrições, papiros, LXX; TestSol 9:7 P; TestJos 7:2; JosAs 29:4; ApcrEzk P 1, verso, 2 [reconstituído]; Fílon; apologistas, exceto Aristides).</p><p class=\"entry-text\">① Prestar serviço ou homenagem, servir a uma divindade (Hesíodo, Heródoto e posteriores; Diodoro Sículo 5, 44, 2 <span class=\"greek\">οἱ</span> <span class=\"greek\">θεραπεύοντες</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἱερεῖς</span>; Arriano, Anab. 7, 2, 4; OGI 90, 40; SIG 663, 6; 996, 30; 1042, 10; Michel 982, 14; PGiss 20, 20; LXX [Thackeray p. 8]; EpArist 256; Fílon, Spec. Leg. 2, 167; Josefo, Bell. 7, 424; Ant. 4, 67; Atenágoras 16, 1 e 3; Orígenes, C. Cels. 8, 12, 17). Passiva com <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χειρῶν</span> <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">θεραπεύεται</span>, «nem é servido por mãos humanas», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:25</a> (Field, Notes 127).</p><p class=\"entry-text\">② Curar, restabelecer (Ateneu 12, p. 522b; SIG 1004, 21; 1168, 126; 1170, 20; 1171, 7; 1172, 5; Tb 12:3; Sir 38:7; JosAs; apologistas, exceto Aristides; Hipólito, Ref. 4, 44, 2; há uma transição natural para esse significado a partir dos vários usos de <span class=\"greek\">θ</span>. com o sentido de «cuidar de, atender, tratar medicamente»).</p><p class=\"entry-text\">Com acusativo <span class=\"greek\">τινά</span>, «alguém» (Josefo, Bell. 1, 272; de Jesus, Orígenes, C. Cels. 2, 64, 17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>; 8:7, 16; 10:8; 12:15, 22; 14:14; 15:30; 17:16, 18; 19:2; 21:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:34</a>; 3:2, 10; 6:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:23</a> (Horapolo 2, 76 <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">θεραπευθείς</span>), 40; 10:9; 13:14b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:14</a>; 5:16; 8:7; 28:9; Qua; AcPl Ha 5, 36; 8, 36 = AcPl BMM, verso, 10 (cego).</p><p class=\"entry-text\"><span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, «curar alguém de uma enfermidade» (BGU 956, 2 <span class=\"greek\">ἐξορκίζω</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">θεραπεῦσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Διονύσιον</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ῥίγου</span> [= <span class=\"greek\">ῥίγους</span>] <span class=\"greek\">καὶ</span> <span class=\"greek\">πυρετοῦ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:21</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:15</a>; 6:18; 8:2 (Taciano 16:3 e outros). <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> tem significado diferente no versículo 43: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἴσχυσεν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐδενὸς</span> <span class=\"greek\">θεραπευθῆναι</span>, «não pôde ser curada por ninguém».</p><p class=\"entry-text\"><span class=\"greek\">θ</span>. <span class=\"greek\">νόσον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαλακίαν</span> (cf. Fílon, Det. Pot. Insid. 43; Josefo, Ant. 17, 150), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>; 9:35; 10:1; (<span class=\"greek\">τὰς</span>) <span class=\"greek\">νόσους</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:15</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:1</a> (Justino, A I, 48, 1; cf. 54, 10). De feridas, na passiva (cf. Irineu 1, 3, 3 [Harvey I 27, 4]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 13:3</a>, 12; feridas tratadas com emplastro, IPol 2:1. AcPl BMM, verso, 14 <span class=\"greek\">θ̣ε̣ρα</span>[<span class=\"greek\">πεύων</span>] (devido a uma lacuna não se pode determinar o objeto). Uso absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:7</a>; 9:6; 13:14; 14:3.</p><p class=\"entry-text\">Figuradamente, em ocorrências isoladas (por exemplo, Vi. Aesopi I, cap. 98 <span class=\"greek\">τὴν</span> <span class=\"greek\">ὀργὴν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">θεραπεύσει</span>): acerca de Deus (Sb 16:12), <span class=\"greek\">ὁ</span> <span class=\"greek\">θεραπεύων</span> <span class=\"greek\">θεός</span>, «Deus, que pode curar», 2Cl 9:7 (<span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">θεραπεύων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζωοποιῶν</span>, Teófilo de Antioquia 1, 7 [p. 72, 17]; acerca de Cristo, Dídimo, Gen. 105, 16; cf. Shmone Esre 8 רוֹפֵא … אֵל). — J. Hempel, Heilung als Symbol u. Wirklichkeit, ’58; J. Dewey, Jesus’ Healings of Women, BTB 24, ’94, 122–31; J. Carroll, Sickness and Healing in the NT Gospels, Int 49, ’95, 130–42. Sobre a prática médica no mundo greco-romano, ver ANRW II/37/1–3, ’93–96. B. 306; DELG, s.v. <span class=\"greek\">θεράπων</span>; M-M; EDNT; TRE XIV 763–68; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θεράπων, οντος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver os dois verbetes precedentes; Homero e posteriores; Alcífron 4, 19, 9 <span class=\"greek\">Διονύσου</span> <span class=\"greek\">θ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">προφήτης</span>; SIG 219, 12; 1168, 114s. <span class=\"greek\">οἱ</span> <span class=\"greek\">θεράποντες</span> do templo de Asclépio; BGU 361 III, 18; LXX [Thackeray p. 7s.]; TestSol, TestJob; TestLevi 4:2; ApcMos, prólogo; Fílon.) Pessoa que presta serviço dedicado, especialmente como assistente em contexto cultual; assistente, auxiliar, servo. Na literatura considerada, empregado somente a respeito de Moisés (como em Êx 4:10; 14:31; Nm 12:7 [em Justino, D. 46, 3 e outros]; Sb 10:16; Teófilo de Antioquia 3, 18 [p. 240, 13]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:5</a>; 1Cl 4:12; 43:1; 51:3; cf. v. 5; 53:5; B 14:4. — B. 1334; DELG; M-M; TW; Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θερεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Substantivo formado a partir da forma feminina do adjetivo <span class=\"greek\">θέρειος</span> [subentende-se <span class=\"greek\">ὥρα</span>]; Píndaro e outros; Aristóteles; Diodoro Sículo; papiros; En 2:3; Josefo, C. Ap. 1, 79.) Estação de verão, Hs 4:2 (variante de leitura <span class=\"greek\">θρόνος</span>), 3 e 5 (variante de leitura <span class=\"greek\">θέρος</span>). — DELG, s.v. <span class=\"greek\">θέρομαι</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θερίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">Futuro <span class=\"greek\">θερίσω</span>, mas 3ª pessoa do plural <span class=\"greek\">θεριοῦσι</span>, Jó 4:8; Sl 125:5; 1º aoristo <span class=\"greek\">ἐθέρισα</span>. Passiva: 1º aoristo <span class=\"greek\">ἐθερίσθην</span>; particípio perfeito passivo, neutro plural <span class=\"greek\">τεθερισμένα</span>, Jdt 4:5 (ver <span class=\"greek\">θερισμός</span>; pré-socráticos, trágicos e posteriores; inscrições, papiros, LXX, TestLevi 13:6; Fílon; Josefo, Ant. 3, 251 e outros; Hipólito, Ref. 5, 8, 39; Dídimo, Gen. 33, 2).</p><p class=\"entry-text\">① Colher uma safra de cereais por meio da ceifa; ceifar, colher. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:24</a>; 1Cl 56:15 (Jó 5:26); <span class=\"greek\">ὁ</span> <span class=\"greek\">θερίσας</span>, «o ceifeiro», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:4</a> (cf. BGU 349, 10 <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μισθωσαμένου</span> <span class=\"greek\">θερίζοντος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μισθῷ</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:36</a>. — Dalman, Arbeit III.</p><p class=\"entry-text\">② Obter resultados ou benefícios; colher, extensão figurada do sentido 1.</p><p class=\"entry-text\">ⓐ Especialmente em expressões proverbiais (Paroem. Gr., Diogeniano 2, 62): <span class=\"greek\">ἄλλος</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σπείρων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄλλος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θερίζων</span>, «um semeia, outro ceifa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:37</a>; cf. v. 38. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">σπείρῃ</span> <span class=\"greek\">ἄνθρωπος</span>, <span class=\"greek\">τοῦτο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θερίσει</span>, «aquilo que o homem semear, isso também colherá», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:7</a> (cf. Aristóteles, Rhet. 3, 3, 4 [1406b 9s.], citando Górgias <span class=\"greek\">σὺ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">αἰσχρῶς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἔσπειρας</span> <span class=\"greek\">κακῶς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἐθέρισας</span>; Platão, Phdr. 260d; Fílon, Leg. ad Gai. 293). <span class=\"greek\">θερίζων</span> <span class=\"greek\">ὅπου</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔσπειρας</span>, «colhendo onde não semeaste», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:24</a>, 26; Lc 19:21s. Da recompensa em geral (TestLevi 13:6 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">σπείρητε</span> <span class=\"greek\">πονηρά</span>, <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ταραχὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θλῖψιν</span> <span class=\"greek\">θερίσετε</span>; Fílon, Conf. Lingu. 152; Jr 12:13; Pv 22:8), <span class=\"greek\">φθοράν</span>, <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span>, «corrupção, vida eterna», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:8</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">σαρκικὰ</span> <span class=\"greek\">ὑμῶν</span>, «colher (= reivindicar) vossos bens materiais», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9:11</a>. Uso absoluto: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 6:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:6</a>.</p><p class=\"entry-text\">ⓑ Acerca da colheita do Juízo Final, que traz devastação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:15</a>. <span class=\"greek\">ἐθερίσθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span>, «a terra foi ceifada», v. 16 (cf. Plutarco, Mor. 182a <span class=\"greek\">θερίζειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἀσίαν</span>). — B. 506; DELG, s.v. <span class=\"greek\">θέρομαι</span> 2; M-M; EDNT; TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θερινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Píndaro e outros; Sb 358, 7; 14 [inscrição do séc. III a.C.]; BGU 1188, 9 [séc. I a.C.]; POxy 810; LXX; Fílon; Josefo, Ant. 15, 54.) De verão, estival: <span class=\"greek\">καιροί</span>, «estações do verão», 1Cl 20:9. — DELG, s.v. <span class=\"greek\">θέρομαι</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0167-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">θερισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Ver <span class=\"greek\">θερίζω</span>; Xenofonte, Oec. 18, 3; Políbio 5, 95, 5; PLille 1, verso, 9 [séc. III a.C.]; PHib 90, 5; BGU 594, 5; LXX; JosAs 2:19 <span class=\"greek\">καιρὸς</span> … <span class=\"greek\">θερισμοῦ</span>; EpArist 116; Fílon, Somn. 2, 23.)</p><p class=\"entry-text\">① Processo (e época) de colher, ceifa, colheita. <span class=\"greek\">ἕως</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θερισμοῦ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:30a</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θερισμοῦ</span>, v. 30b (cf. Jr 27:16 <span class=\"greek\">ἐν</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">θ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:29</a>. Nessas parábolas, <span class=\"greek\">θερισμός</span> serve para explicar procedimentos do reino de Deus, como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:39</a> demonstra claramente. A época da colheita constitui pano de fundo da discussão sobre a missão apostólica e o julgamento que se aproxima, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:35a</a> (ver 2b).</p><p class=\"entry-text\">② Safra que deve ser colhida, colheita; extensão figurada do sentido 1.</p><p class=\"entry-text\">ⓐ Acerca de pessoas que hão de ser conquistadas, Mt 9:37s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 10:2</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:35b</a>, o evangelista talvez combine uma observação agrícola com uma afirmação sobre a missão apostólica; <span class=\"greek\">πρὸς</span> <span class=\"greek\">θερισμόν</span> em sentido passivo, «destinadas a ser ceifadas».</p><p class=\"entry-text\">ⓑ Acerca do julgamento iminente: <span class=\"greek\">ἐξηράνθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, «a colheita da terra está seca (= completamente madura)», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:15</a>. — DELG, s.v. <span class=\"greek\">θέρομαι</span> 2; M-M; TW.</p></section></article>\n"};
